			// b's coordinates) intersect with one or other of b's child nodes?
			AABBd rotAabb = rotateAaabb(edgeNode->aabb, transTo);
			const bool left = rotAabb.Intersects(triBvh->GetNode(triNode->kids[0])->aabb);
