    vi=m.find('c:vertices',ns); vsrc=vi.find('c:input',ns).get('source')[1:]; P=srcs[vsrc]
    for prim in list(m.findall('c:triangles',ns))+list(m.findall('c:polylist',ns)):
        inputs=prim.findall('c:input',ns); stride=max(int(i.get('offset')) for i in inputs)+1
        off=[int(i.get('offset')) for i in inputs if i.get('semantic')=='VERTEX'][0]
        idx=list(map(int,prim.find('c:p',ns).text.split()))
        vc=prim.find('c:vcount',ns); counts=list(map(int,vc.text.split())) if vc is not None else [3]*(len(idx)//stride//3)
        pos=0
        for c in counts:
            poly=[idx[(pos+k)*stride+off] for k in range(c)]; pos+=c
            for k in range(1,c-1):
                yield [P[3*poly[0]:3*poly[0]+3],P[3*poly[k]:3*poly[k]+3],P[3*poly[k+1]:3*poly[k+1]+3]]
