        for e in ch:
            if e.tag.endswith('matrix'): a=list(map(float,e.text.split())); m=mm(m,[a[i:i+4] for i in range(0,16,4)])
        W=mm(M,m)
        ig=ch.find('c:instance_geometry',ns)
        if ig is not None:
            zs=[]
            for t in tris(geo[ig.get('url')[1:]]):
                tw=[ap(W,v) for v in t]
                c=[sum(v[i] for v in tw)/3 for i in range(3)]
